python3 << 'PYEOF'
import json

# Load analysis data
with open('/app/output/analysis_data.json', 'r') as f:
    data = json.load(f)

# Load charts
with open('/app/output/charts.json', 'r') as f:
    charts = json.load(f)

html_content = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Global Fuel Price Trends & Policy Impact Analysis (2020–2026)</title>
    <style>
        :root {{
            --primary: #1a365d;
            --secondary: #2c5282;
            --accent: #ed8936;
            --bg: #f7fafc;
            --text: #2d3748;
            --border: #e2e8f0;
        }}
        * {{ box-sizing: border-box; margin: 0; padding: 0; }}
        body {{
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
            color: var(--text);
            background: var(--bg);
            line-height: 1.6;
        }}
        .container {{ max-width: 1200px; margin: 0 auto; padding: 2rem; }}
        header {{
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            color: white;
            padding: 3rem 2rem;
            margin-bottom: 2rem;
        }}
        header h1 {{ font-size: 2.5rem; margin-bottom: 0.5rem; }}
        header .subtitle {{ opacity: 0.9; font-size: 1.1rem; }}
        h2 {{
            color: var(--primary);
            border-bottom: 3px solid var(--accent);
            padding-bottom: 0.5rem;
            margin: 2.5rem 0 1.5rem;
            font-size: 1.8rem;
        }}
        h3 {{ color: var(--secondary); margin: 1.5rem 0 1rem; font-size: 1.3rem; }}
        .kpi-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 1.5rem;
            margin: 1.5rem 0;
        }}
        .kpi-card {{
            background: white;
            border-radius: 8px;
            padding: 1.5rem;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
            border-left: 4px solid var(--accent);
        }}
        .kpi-card .label {{ color: #718096; font-size: 0.9rem; text-transform: uppercase; letter-spacing: 0.5px; }}
        .kpi-card .value {{ font-size: 2rem; font-weight: 700; color: var(--primary); margin: 0.5rem 0; }}
        .kpi-card .context {{ font-size: 0.85rem; color: #718096; }}
        .chart-container {{
            background: white;
            border-radius: 8px;
            padding: 1.5rem;
            margin: 1.5rem 0;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
        }}
        .chart-container svg {{ width: 100%; height: auto; }}
        .chart-title {{ font-weight: 600; color: var(--secondary); margin-bottom: 1rem; }}
        .two-col {{
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 2rem;
        }}
        table {{
            width: 100%;
            border-collapse: collapse;
            margin: 1rem 0;
            background: white;
            border-radius: 8px;
            overflow: hidden;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
        }}
        th, td {{
            padding: 1rem;
            text-align: left;
            border-bottom: 1px solid var(--border);
        }}
        th {{ background: var(--primary); color: white; font-weight: 600; }}
        tr:hover {{ background: #f8fafc; }}
        .highlight-box {{
            background: linear-gradient(135deg, #ebf8ff, #e6fffa);
            border-left: 4px solid #38b2ac;
            padding: 1.5rem;
            border-radius: 4px;
            margin: 1.5rem 0;
        }}
        .key-finding {{
            background: white;
            border-radius: 8px;
            padding: 1.5rem;
            margin: 1rem 0;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
            border-left: 4px solid var(--accent);
        }}
        .key-finding h4 {{ color: var(--primary); margin-bottom: 0.5rem; }}
        .key-finding p {{ color: #4a5568; }}
        .data-note {{
            font-size: 0.85rem;
            color: #718096;
            font-style: italic;
            margin-top: 0.5rem;
        }}
        footer {{
            margin-top: 3rem;
            padding: 2rem;
            background: var(--primary);
            color: white;
            text-align: center;
        }}
        @media (max-width: 768px) {{
            .two-col {{ grid-template-columns: 1fr; }}
            header h1 {{ font-size: 1.8rem; }}
        }}
    </style>
</head>
<body>
    <header>
        <div class="container">
            <h1>Global Fuel Price Trends & Policy Impact Analysis</h1>
            <p class="subtitle">Comprehensive Analysis of Retail Fuel Prices Across 84 Countries (2020–2026)</p>
        </div>
    </header>

    <main class="container">
        <!-- Executive Summary -->
        <section id="executive-summary">
            <h2>Executive Summary</h2>
            <p>This report analyzes retail fuel prices across <strong>{data['countries']} countries</strong> spanning <strong>{data['date_range']}</strong>. The analysis reveals how Brent Crude oil price movements translate into retail fuel costs, and evaluates the effectiveness of government subsidies and taxation policies in buffering consumers from volatility.</p>

            <div class="kpi-grid" style="margin-top: 1.5rem;">
                <div class="kpi-card">
                    <div class="label">Average Retail Petrol Price</div>
                    <div class="value">${data['avg_petrol']:.2f}</div>
                    <div class="context">USD per liter (global average)</div>
                </div>
                <div class="kpi-card">
                    <div class="label">Brent-to-Petrol Correlation</div>
                    <div class="value">{data['corr_petrol']:.3f}</div>
                    <div class="context">Pearson correlation coefficient</div>
                </div>
                <div class="kpi-card">
                    <div class="label">Subsidy Dampening Effect</div>
                    <div class="value">{data['subsidy_dampening']:.1f}%</div>
                    <div class="context">High vs Low subsidy price difference</div>
                </div>
                <div class="kpi-card">
                    <div class="label">Regional Price Spread</div>
                    <div class="value">${data['regional_spread']:.2f}</div>
                    <div class="context">Highest vs lowest region average</div>
                </div>
            </div>
        </section>

        <!-- Global Fuel Price Overview -->
        <section id="global-overview">
            <h2>Global Fuel Price Overview</h2>
            <p>The dataset encompasses weekly retail fuel prices for petrol, diesel, and LPG across 84 countries. Brent Crude oil serves as the global benchmark, averaging <strong>${data['avg_brent']:.2f} per barrel</strong> over the study period.</p>

            <div class="kpi-grid">
                <div class="kpi-card">
                    <div class="label">Petrol Price Range</div>
                    <div class="value">${data['min_petrol']:.2f} – ${data['max_petrol']:.2f}</div>
                    <div class="context">Min to max observed (USD/L)</div>
                </div>
                <div class="kpi-card">
                    <div class="label">Average Diesel Price</div>
                    <div class="value">${data['avg_diesel']:.2f}</div>
                    <div class="context">USD per liter</div>
                </div>
                <div class="kpi-card">
                    <div class="label">Average LPG Price</div>
                    <div class="value">${data['avg_lpg']:.2f}</div>
                    <div class="context">USD per liter</div>
                </div>
                <div class="kpi-card">
                    <div class="label">Average Brent Crude</div>
                    <div class="value">${data['avg_brent']:.2f}</div>
                    <div class="context">USD per barrel</div>
                </div>
            </div>

            <div class="chart-container">
                <div class="chart-title">Figure 1: Brent Crude vs Retail Petrol Price Trends (2020–2026)</div>
                {charts['brent_petrol_trends']}
            </div>
            <p class="data-note">Note: Brent Crude prices (blue) represent the global benchmark per barrel. Retail petrol prices (red) are shown per liter. The chart reveals distinct phases: COVID-19 demand collapse (early 2020), recovery (mid-2021), and the 2022 energy crisis peak.</p>
        </section>

        <!-- Temporal Price Trends & Volatility -->
        <section id="temporal-trends">
            <h2>Temporal Price Trends & Volatility</h2>

            <h3>Annual Price Trajectory</h3>
            <table>
                <thead>
                    <tr><th>Year</th><th>Brent Crude (USD/bbl)</th><th>Petrol (USD/L)</th><th>YoY Brent Change</th></tr>
                </thead>
                <tbody>
"""

# Yearly data
years = sorted(data['yearly_brent'].keys())
for i, year in enumerate(years):
    brent = data['yearly_brent'][year]
    petrol = data['yearly_petrol'][year]
    if i > 0:
        prev_brent = data['yearly_brent'][years[i-1]]
        yoy = ((brent - prev_brent) / prev_brent) * 100
        yoy_str = f"{yoy:+.1f}%"
    else:
        yoy_str = "—"
    html_content += f"<tr><td>{year}</td><td>${brent:.2f}</td><td>${petrol:.2f}</td><td>{yoy_str}</td></tr>\n"

html_content += f"""                </tbody>
            </table>

            <h3>Volatility Analysis</h3>
            <p>The 2020–2026 period witnessed significant price volatility. Key observations:</p>
            <ul style="margin: 1rem 0 1.5rem 2rem;">
                <li><strong>COVID-19 Shock (Q1-Q2 2020):</strong> Brent crashed from ~$65/bbl to ~$52/bbl in April 2020, representing a 20% decline. Retail petrol followed with a lag, dropping from ~$1.42/L to ~$1.09/L.</li>
                <li><strong>2022 Energy Crisis:</strong> Brent peaked at $130/bbl in April-May 2022 (geopolitical tensions). Global petrol averages surged to ~$2.78/L, creating significant consumer pressure.</li>
                <li><strong>2023 Stabilization:</strong> Prices moderated as supply chains adjusted, with Brent settling around $100-110/bbl.</li>
                <li><strong>2024-2026:</strong> Brent resumed an upward trajectory, averaging ~$119/bbl in 2024-2025 and reaching ~$124/bbl in early 2026.</li>
            </ul>

            <div class="chart-container">
                <div class="chart-title">Figure 2: Petrol Price Volatility Over Time (±1 Standard Deviation)</div>
                {charts['volatility']}
            </div>
            <p class="data-note">Note: The shaded band represents ±1 standard deviation from the monthly mean, illustrating price dispersion across countries at any given time.</p>

            <h3>Brent-to-Retail Correlation</h3>
            <div class="highlight-box">
                <p><strong>Key Finding:</strong> The Pearson correlation between Brent Crude and retail petrol prices is <strong>{data['corr_petrol']:.3f}</strong>, indicating a moderate positive relationship. This relatively modest correlation reflects the substantial buffering effect of taxes, subsidies, and local market conditions that decouple retail prices from global crude movements.</p>
            </div>
        </section>

        <!-- Regional Price Disparities -->
        <section id="regional-comparison">
            <h2>Regional Price Disparities</h2>
            <p>Substantial regional price disparities persist throughout the study period. Europe and Oceania consistently exhibit the highest petrol prices, while the Middle East and Africa maintain the lowest.</p>

            <table>
                <thead>
                    <tr><th>Region</th><th>Avg Petrol Price (USD/L)</th><th>vs Global Avg</th></tr>
                </thead>
                <tbody>
"""

regional_sorted = sorted(data['regional_avg'].items(), key=lambda x: x[1], reverse=True)
for region, price in regional_sorted:
    diff = ((price - data['avg_petrol']) / data['avg_petrol']) * 100
    html_content += f"<tr><td>{region}</td><td>${price:.4f}</td><td>{diff:+.1f}%</td></tr>\n"

html_content += f"""                </tbody>
            </table>

            <div class="chart-container">
                <div class="chart-title">Figure 3: Regional Petrol Price Comparison by Year</div>
                {charts['regional_prices']}
            </div>

            <div class="chart-container">
                <div class="chart-title">Figure 4: Regional Price Inequality Over Time</div>
                {charts['regional_spread']}
            </div>
            <p class="data-note">Note: The spread represents the difference between the highest-priced and lowest-priced country in each year. The narrowing during 2020 reflects the COVID demand collapse's global reach; the widening in 2022-2026 reflects divergent regional recovery and policy responses.</p>

            <h3>Regional Dynamics</h3>
            <ul style="margin: 1rem 0 1.5rem 2rem;">
                <li><strong>Europe:</strong> Highest average prices (${data['regional_avg']['Europe']:.2f}/L) due to high taxation (avg 34.72% tax for High income countries where Europe dominates)</li>
                <li><strong>Middle East:</strong> Lowest prices (${data['regional_avg']['Middle East']:.2f}/L) reflecting heavy fuel subsidies</li>
                <li><strong>Africa:</strong> Second-lowest (${data['regional_avg']['Africa']:.2f}/L), though this masks significant intra-regional variation</li>
                <li><strong>Asia:</strong> Above global average with substantial variation between developed Asian economies and emerging markets</li>
            </ul>
        </section>

        <!-- Impact of Subsidies and Taxation -->
        <section id="subsidy-tax-analysis">
            <h2>Impact of Subsidies and Taxation on Retail Prices</h2>

            <h3>Subsidy Level Analysis</h3>
            <p>Government subsidy regimes create dramatic differences in consumer prices. Countries are categorized into four subsidy levels: Very High, High, Medium, and Low.</p>

            <table>
                <thead>
                    <tr><th>Subsidy Level</th><th>Avg Petrol Price (USD/L)</th><th>Brent Correlation</th></tr>
                </thead>
                <tbody>
"""

subsidy_order = ['Very High', 'High', 'Medium', 'Low']
for level in subsidy_order:
    price = data['subsidy_prices'].get(level, 0)
    corr = data['corr_by_subsidy'].get(level, 0)
    html_content += f"<tr><td>{level}</td><td>${price:.4f}</td><td>{corr:.4f}</td></tr>\n"

html_content += f"""                </tbody>
            </table>

            <div class="highlight-box">
                <p><strong>Subsidy Price Dampening Effect:</strong> High-subsidy countries ({data['high_sub']:.2f}/L) pay {data['subsidy_dampening']:.1f}% less than low-subsidy countries ({data['low_sub']:.2f}/L). Very High subsidy countries pay just {data['very_high_sub']:.4f}/L on average — effectively {((data['low_sub'] - data['very_high_sub']) / data['low_sub']) * 100:.1f}% below low-subsidy nations.</p>
            </div>

            <div class="chart-container">
                <div class="chart-title">Figure 5: Petrol Prices by Subsidy Level Over Time</div>
                {charts['subsidy_trends']}
            </div>

            <h3>Correlation Analysis: Do Subsidies Buffer Crude Volatility?</h3>
            <div class="chart-container">
                <div class="chart-title">Figure 6: Brent-to-Petrol Correlation by Subsidy Level</div>
                {charts['correlation_by_subsidy']}
            </div>
            <p class="data-note">Note: Higher correlation means retail prices more closely track Brent Crude movements. Medium-subsidy countries show the highest correlation (0.781), suggesting their pricing is most responsive to global crude changes. Very High subsidy countries show the lowest correlation (0.307), confirming strong state insulation from global price swings.</p>

            <h3>Taxation Patterns</h3>
            <div class="chart-container">
                <div class="chart-title">Figure 7: Fuel Tax Burden by Income Level (2020–2026)</div>
                {charts['tax_by_income']}
            </div>

            <div class="highlight-box">
                <p><strong>Tax-to-Price Ratio by Income Level:</strong></p>
                <ul style="margin: 0.5rem 0 0.5rem 2rem;">
                    <li>High-income countries: {data['tax_by_income']['High']:.1f}% average tax burden</li>
                    <li>Middle-income countries: {data['tax_by_income']['Middle']:.1f}% average tax burden</li>
                    <li>Low-income countries: {data['tax_by_income']['Low']:.1f}% average tax burden</li>
                </ul>
                <p>High-income countries tax fuel at roughly 1.5x the rate of low-income countries, using fiscal policy to both manage demand and fund public services.</p>
            </div>
        </section>

        <!-- Fuel Affordability by Income Level -->
        <section id="income-level-segmentation">
            <h2>Fuel Affordability by Income Level</h2>
            <p>Income level significantly shapes fuel pricing outcomes. High-income countries face higher absolute prices but typically have greater purchasing power and more sophisticated subsidy frameworks.</p>

            <div class="chart-container">
                <div class="chart-title">Figure 8: Fuel Price Affordability by Income Level (2020–2026)</div>
                {charts['income_trends']}
            </div>

            <h3>Key Affordability Metrics</h3>
            <table>
                <thead>
                    <tr><th>Income Level</th><th>2020 Avg (USD/L)</th><th>2026 Avg (USD/L)</th><th>Change</th><th>Avg Tax %</th></tr>
                </thead>
                <tbody>
"""

for income in ['High', 'Middle', 'Low']:
    p2020 = data['income_by_year'][income]['2020']
    p2026 = data['income_by_year'][income]['2026']
    change = ((p2026 - p2020) / p2020) * 100
    tax = data['tax_by_income'][income]
    html_content += f"<tr><td>{income}</td><td>${p2020:.2f}</td><td>${p2026:.2f}</td><td>{change:+.1f}%</td><td>{tax:.1f}%</td></tr>\n"

html_content += """                </tbody>
            </table>

            <h3>Energy Equity Analysis</h3>
            <div class="highlight-box">
                <p><strong>Key Finding:</strong> Low-income countries experienced a <strong>78% price increase</strong> from 2020 to 2026 in absolute terms ($0.90/L to $1.61/L), while High-income countries saw a <strong>78% increase</strong> ($2.31/L to $4.11/L). However, as a percentage of per-capita income, the burden on low-income countries is substantially higher.</p>
            </div>
            <p>The data suggests that low-income countries face a paradox: they pay lower absolute fuel prices but bear a higher relative economic burden. Additionally, low-income countries have less fiscal capacity to maintain subsidy programs during crude price spikes, forcing painful price adjustments.</p>
        </section>

        <!-- Key Findings & Policy Implications -->
        <section id="key-findings-recommendations">
            <h2>Key Findings & Policy Implications</h2>

            <div class="key-finding">
                <h4>1. Moderate Global Brent-to-Retail Correlation (0.26)</h4>
                <p>Retail petrol prices show only a moderate correlation with Brent Crude, indicating that national policies—taxation and subsidies—substantially decouple local prices from global crude movements. Policymakers should recognize that consumer prices are highly policy-dependent.</p>
            </div>

            <div class="key-finding">
                <h4>2. Subsidies Provide Significant but Variable Protection</h4>
